import { createHash } from "node:crypto";
import { SHA256_BASE64, UPLOAD_UUID, VIDEO_PART_BYTES, VIDEO_UPLOAD_MAX_BYTES, videoPartSize } from "@/lib/video-upload-policy

const signedHeaders = (url.searchParams.get("X-Amz-SignedHeaders") || "").split(";");
if (!["content-type", "content-length", "if-none-match"].every(name => signedHeaders.includes(name))) throw new Error("Missing signed upload constraint");
client.destroy();

export type UploadedPart = { partNumber: number; size: number; etag: string; checksum: string };
function uploadSignal(signal?: AbortSignal) {
  const deadline = AbortSignal.timeout(10_000);
  return signal ? AbortSignal.any([signal, deadline]) : deadline;
}
function multipartContext(key: string, uploadId?: string) {
  const normalized = normalizeStorageKey(key);
  if (!normalized.startsWith("private/video-source/") || uploadId !== undefined && (!uploadId || uploadId.length > 2048 || /[\u0000-\u0020\u007f]/.test(uploadId))) throw new Error("Invalid multipart context");
  return normalized;
}
function missingUpload(error: unknown) {
  const value = error as { name?: string; Code?: string };
  return value.name === "NoSuchUpload" || value.Code === "NoSuchUpload";
}

export function multipartCompositeChecksum(checksums: string[]) {
  if (!checksums.length || checksums.some(value => !SHA256_BASE64.test(value))) throw new Error("Invalid multipart checksums");
  return createHash("sha256").update(Buffer.concat(checksums.map(value => Buffer.from(value, "base64")))).digest("base64") + `-${checksums.length}`;
}

export async function startMultipartUpload(key: string, contentType: string, sessionId: string, signal?: AbortSignal) {
  const normalizedKey = multipartContext(key);
  if (!validContentType(contentType) || !UPLOAD_UUID.test(sessionId)) throw new Error("Invalid multipart metadata");
  const { client, bucket } = getStorageConfig();
  try {
    const result = await client.send(new CreateMultipartUploadCommand({ Bucket: bucket, Key: normalizedKey,
      ContentType: contentType, ChecksumAlgorithm: "SHA256", ChecksumType: "COMPOSITE",
      Metadata: { "maras-upload-session": sessionId } }), { abortSignal: uploadSignal(signal) });
    if (!result.UploadId) throw new Error("Multipart upload ID missing");
    return result.UploadId;
  } finally { client.destroy(); }
}

export async function signMultipartPart(key: string, uploadId: string, partNumber: number, sizeBytes: number, checksum: string, ttl = 300) {
  const normalizedKey = multipartContext(key, uploadId);
  if (!Number.isSafeInteger(partNumber) || partNumber < 1 || partNumber > Math.ceil(VIDEO_UPLOAD_MAX_BYTES / VIDEO_PART_BYTES)
      || !Number.isSafeInteger(sizeBytes) || sizeBytes < 1 || sizeBytes > VIDEO_PART_BYTES || !SHA256_BASE64.test(checksum)
      || !Number.isSafeInteger(ttl) || ttl < 60 || ttl > 900) throw new Error("Invalid multipart signing constraints");
  const { client, bucket, endpoint, forcePathStyle } = getStorageConfig();
  try {
    const uploadUrl = await getSignedUrl(client, new UploadPartCommand({ Bucket: bucket, Key: normalizedKey,
      UploadId: uploadId, PartNumber: partNumber, ContentLength: sizeBytes, ChecksumSHA256: checksum }), {
      expiresIn: ttl, signableHeaders: new Set(["content-length", "x-amz-checksum-sha256"]),
      unhoistableHeaders: new Set(["x-amz-checksum-sha256"]),
    });
    const url = new URL(uploadUrl), headers = (url.searchParams.get("X-Amz-SignedHeaders") || "").split(";");
    const host = forcePathStyle ? endpoint.hostname : `${bucket}.${endpoint.hostname}`;
    const path = endpoint.pathname.replace(/\/$/, "") + (forcePathStyle ? `/${bucket}` : "") + "/" + normalizedKey.split("/").map(segment => encodeURIComponent(segment).replace(/[!'()*]/g, char => `%${char.charCodeAt(0).toString(16).toUpperCase()}`)).join("/");
    if (url.protocol !== endpoint.protocol || url.hostname !== host || url.port !== endpoint.port || url.pathname !== path
        || url.searchParams.get("uploadId") !== uploadId || Number(url.searchParams.get("partNumber")) !== partNumber
        || Number(url.searchParams.get("X-Amz-Expires")) !== ttl || !["content-length", "x-amz-checksum-sha256"].every(name => headers.includes(name))) throw new Error("Unexpected multipart signature");
    // Content-Length is set automatically by the browser for the exact Blob slice;
    // JavaScript must not try to set a forbidden request header.
    return { uploadUrl, headers: { "x-amz-checksum-sha256": checksum } };
  } finally { client.destroy(); }
}

export async function listMultipartParts(key: string, uploadId: string, signal?: AbortSignal): Promise<UploadedPart[] | null> {
  const normalizedKey = multipartContext(key, uploadId), { client, bucket } = getStorageConfig();
  try {
    const result = await client.send(new ListPartsCommand({ Bucket: bucket, Key: normalizedKey, UploadId: uploadId, MaxParts: 1000 }), { abortSignal: uploadSignal(signal) });
    // The 2 GB/8 MiB contract cannot have 1000 parts. A truncated list is corrupt,
    // not permission to complete an unchecked tail.
    if (result.IsTruncated) throw new Error("Multipart list exceeds the fixed part budget");
    const seen = new Set<number>();
    return (result.Parts ?? []).map(part => {
      if (!Number.isSafeInteger(part.PartNumber) || !part.PartNumber || seen.has(part.PartNumber)
          || !Number.isSafeInteger(part.Size) || !part.Size || !part.ETag || !part.ChecksumSHA256 || !SHA256_BASE64.test(part.ChecksumSHA256)) throw new Error("Invalid multipart part metadata");
      seen.add(part.PartNumber);
      return { partNumber: part.PartNumber, size: part.Size, etag: part.ETag, checksum: part.ChecksumSHA256 };
    });
  } catch (error) { if (missingUpload(error)) return null; throw error; }
  finally { client.destroy(); }
}

export async function completeMultipartUpload(key: string, uploadId: string, parts: UploadedPart[], sizeBytes: number, signal?: AbortSignal) {
  const normalizedKey = multipartContext(key, uploadId);
  if (!Number.isSafeInteger(sizeBytes) || sizeBytes < 1 || sizeBytes > VIDEO_UPLOAD_MAX_BYTES
      || parts.length !== Math.ceil(sizeBytes / VIDEO_PART_BYTES)
      || parts.some((part, index) => part.partNumber !== index + 1 || part.size !== videoPartSize(sizeBytes, part.partNumber)
        || !SHA256_BASE64.test(part.checksum) || !part.etag || part.etag.length > 200 || /[\r\n<>]/.test(part.etag))) throw new Error("Invalid complete multipart manifest");
  const { client, bucket } = getStorageConfig();
  try {
    await client.send(new CompleteMultipartUploadCommand({ Bucket: bucket, Key: normalizedKey, UploadId: uploadId,
      IfNoneMatch: "*", MpuObjectSize: sizeBytes, ChecksumType: "COMPOSITE",
      MultipartUpload: { Parts: parts.map(part => ({ PartNumber: part.partNumber, ETag: part.etag, ChecksumSHA256: part.checksum })) },
    }), { abortSignal: signal ? AbortSignal.any([signal, AbortSignal.timeout(60_000)]) : AbortSignal.timeout(60_000) });
  } finally { client.destroy(); }
}

export async function headMultipartUpload(key: string, signal?: AbortSignal) {
  const normalizedKey = multipartContext(key), { client, bucket } = getStorageConfig();
  try {
    const result = await client.send(new HeadObjectCommand({ Bucket: bucket, Key: normalizedKey, ChecksumMode: "ENABLED" }), { abortSignal: uploadSignal(signal) });
    return { size: result.ContentLength, contentType: result.ContentType, sessionId: result.Metadata?.["maras-upload-session"], checksum: result.ChecksumSHA256 };
  } catch (error) { if (isMissingObject(error)) return null; throw error; }
  finally { client.destroy(); }
}

export async function abortMultipartUpload(key: string, uploadId: string, signal?: AbortSignal) {
  const normalizedKey = multipartContext(key, uploadId), { client, bucket } = getStorageConfig();
  try {
    await client.send(new AbortMultipartUploadCommand({ Bucket: bucket, Key: normalizedKey, UploadId: uploadId }), { abortSignal: uploadSignal(signal) });
  } catch (error) { if (!missingUpload(error)) throw error; }
  finally { client.destroy(); }
  // An in-flight part can outlive AbortMultipartUpload. Retry durably until S3
  // confirms that this upload no longer exists; lifecycle expiration is a backstop.
  if (await listMultipartParts(normalizedKey, uploadId, signal) !== null) throw new Error("Multipart abort has not settled");
}
